#!/usr/bin/env python3
"""Add a Chinese legend to the CityPlan PNG generated by the Java planner."""
from __future__ import annotations
import argparse
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont


def font(size: int) -> ImageFont.FreeTypeFont:
    candidates = [
        Path('/System/Library/Fonts/STHeiti Medium.ttc'),
        Path('/System/Library/Fonts/Supplemental/Songti.ttc'),
        Path('/usr/share/fonts/truetype/noto/NotoSansCJK-Regular.ttc'),
    ]
    for path in candidates:
        if path.exists():
            return ImageFont.truetype(str(path), size)
    raise RuntimeError('No CJK font found; install one or extend the font candidate list')


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument('base', type=Path)
    parser.add_argument('output', type=Path)
    args = parser.parse_args()
    base = Image.open(args.base).convert('RGB')
    if base.size != (1024, 1024):
        raise ValueError(f'CityPlan base image must be 1024×1024, got {base.size}')
    image = Image.new('RGB', (1480, 1024), '#101c2b')
    image.paste(base, (0, 0))
    d = ImageDraw.Draw(image)
    heading, title, body, small = font(29), font(23), font(18), font(16)
    d.text((1050, 35), '学园都市 · 地图与交通', font=heading, fill='#f5f8ff')
    d.text((1050, 88), '23 学区 / 当前规划示意', font=body, fill='#afc0d4')
    rows = [
        ('东西动车', '5 站 · 双向往返', '#66f1d1'),
        ('南北动车', '4 站 · 双向往返', '#80b5ff'),
        ('机场接驳', '2 站 · 双向往返', '#ffb744'),
        ('城市环线', '12 站 · 单车每圈换向', '#f06aca'),
        ('地下东西线', '5 站 · 双向往返', '#ff6d63'),
        ('地下南北线', '5 站 · 中央站地下换乘', '#b28aff'),
        ('机场地下线', '4 站 · 航站楼内出入口', '#96dd69'),
    ]
    for index, (name, detail, color) in enumerate(rows):
        y = 141 + index * 62
        d.rounded_rectangle((1050, y + 8, 1080, y + 15), radius=4, fill=color)
        d.text((1093, y - 3), name, font=title, fill='#f4f8fd')
        d.text((1093, y + 27), detail, font=small, fill='#b4c6da')
    d.line((1050, 578, 1440, 578), fill='#46586b', width=2)
    for i, line in enumerate([
        '中央站与北部站可地下换乘。',
        'D7 地铁入口连接西侧林荫步道。',
        '机场地下线连接航站楼。',
        '地图按生成坐标绘制，非实景渲染。',
        '线路与学区布局为改编设计。',
        '各区及交通网络仍需继续完善。',
    ]):
        d.text((1050, 600 + i * 37), line, font=body, fill='#cfdaea')
    args.output.parent.mkdir(parents=True, exist_ok=True)
    image.save(args.output, optimize=True)


if __name__ == '__main__':
    main()
